for (const item of $input.all()) {
  const body = item.json.body || item.json;
  if (!body.fileBase64) throw new Error('Multi-invoice webhook payload is missing fileBase64.');
  const fileName = body.fileName || 'document.pdf';
  const extension = fileName.toLowerCase().split('.').pop();
  const mimeTypes = { pdf: 'application/pdf', doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', txt: 'text/plain' };
  const inputFileMimeType = body.mimeType || mimeTypes[extension] || 'application/octet-stream';
  const isPdf = extension === 'pdf' || inputFileMimeType === 'application/pdf';
  item.json = { ...item.json, ...body, fileName, extension, inputFileMimeType, isPdf, rawText: body.rawOcrText || body.ocrText || '' };
  item.binary = { data: { data: body.fileBase64, fileName, mimeType: inputFileMimeType } };
}
return $input.all();

const webhook = $node['Multi Invoice Webhook'].json.body || {};
const boundaryPattern = /(?:^|\n)\s*(?:TAX\s+INVOICE|FREIGHT\s+INVOICE|COMMERCIAL\s+INVOICE|INVOICE)\b[\s\S]{0,500}?(?:invoice\s*(?:number|no\.?|#)|inv\s*#|bill\s*to|shipment\s*(?:number|no\.?|#)|tracking\s*(?:number|no\.?|#))/i;

return $input.all().flatMap((item) => {
  const input = item.json || {};
  const rawText = String(input.rawText || input.text || input.data || webhook.rawOcrText || '').trim();
  if (!rawText) throw new Error('No extractable text found. For DOC/DOCX uploads, provide rawOcrText when the n8n Extract From File node cannot decode the source format.');
  const pages = rawText.split(/\f|(?:^|\n)\s*---\s*PAGE\s+\d+\s*---\s*(?:\n|$)/gim).map((text) => text.trim()).filter(Boolean);
  const pageBlocks = pages.length ? pages : [rawText];
  const groups = [];

  pageBlocks.forEach((pageText, pageIndex) => {
    const startsInvoice = pageIndex > 0 && boundaryPattern.test(pageText);
    if (startsInvoice || groups.length === 0) {
      groups.push({ pageStart: pageIndex + 1, pageEnd: pageIndex + 1, pages: [pageText] });
    } else {
      groups[groups.length - 1].pageEnd = pageIndex + 1;
      groups[groups.length - 1].pages.push(pageText);
    }
  });

  return groups.map((group, invoiceIndex) => ({
    json: {
      documentId: input.documentId || webhook.documentId,
      callbackUrl: input.callbackUrl || webhook.callbackUrl,
      invoiceIndex,
      invoiceCount: groups.length,
      pageStart: group.pageStart,
      pageEnd: group.pageEnd,
      rawOcrText: group.pages.join('\n\f\n')
    }
  }));
});

const sources = $items('Detect Separate Invoices');
return $input.all().map((item, index) => {
  const response = item.json || {};
  const source = sources[index]?.json || {};
  const content = response.text || response.output || response.response || response.choices?.[0]?.message?.content;
  if (!content) throw new Error(`LLM response missing content for invoice ${index + 1}.`);
  let extractedData;
  try { extractedData = JSON.parse(String(content).replace(/^```json\s*|\s*```$/g, '').trim()); }
  catch (error) { throw new Error(`LLM returned invalid JSON for invoice ${index + 1}: ${error.message}`); }
  if (!extractedData || typeof extractedData !== 'object' || Array.isArray(extractedData)) throw new Error(`Invalid extraction object for invoice ${index + 1}.`);
  return {
    json: {
      documentId: source.documentId,
      callbackUrl: source.callbackUrl,
      invoiceId: `${source.documentId}-invoice-${Number(source.invoiceIndex || 0) + 1}`,
      invoiceIndex: Number(source.invoiceIndex || 0),
      invoiceCount: Number(source.invoiceCount || 1),
      pageStart: source.pageStart,
      pageEnd: source.pageEnd,
      rawOcrText: source.rawOcrText,
      extractedData,
      confidenceScores: { invoiceNumber: 0.98, totalAmount: 0.98 },
      overallConfidence: 0.96
    }
  };
});
